// Verify the HMAC-SHA256 signature Convex put on the envelope,
// then reject stale payloads (replay protection).
const crypto = require('crypto');

const secret = $env.LENDLOOP_WEBHOOK_SECRET;
if (!secret) throw new Error('LENDLOOP_WEBHOOK_SECRET is not set');

const envelope = $input.first().json;
const { body, signature } = envelope;
if (typeof body !== 'string' || typeof signature !== 'string') {
  throw new Error('Malformed payload');
}

const expected = crypto.createHmac('sha256', secret).update(body).digest('hex');
const a = Buffer.from(signature, 'utf8');
const b = Buffer.from(expected, 'utf8');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Invalid signature');
}

const data = JSON.parse(body);
if (typeof data.timestamp !== 'number' || Math.abs(Date.now() - data.timestamp) > 5 * 60 * 1000) {
  throw new Error('Stale payload');
}
return [{ json: data }];

// Mock delivery: logs the notification so it is visible in the
// execution output. Swap this node for Send Email / Slack / Discord
// using only `recipientEmail` — the payload intentionally carries
// nothing else identifying.
const d = $input.first().json;
const subject = d.event === 'request_created'
  ? `New borrow request for "${d.toolName}"`
  : `Your borrow request for "${d.toolName}" was ${d.status}`;
const message = `${subject} (${d.startDate} → ${d.endDate}), from/to ${d.counterpartName}.`;
console.log(`[lendloop] to=${d.recipientEmail} :: ${message}`);
return [{ json: { delivered: true, channel: 'mock-log', to: d.recipientEmail, subject, message } }];
